import json, sys
params = json.load(sys.stdin)
from collections import OrderedDict

def replace_dict_key_case(params, new_case):
    result = {}
    for k, v in params.items():
        if isinstance(v, dict):
            v = replace_dict_key_case(v, new_case)
        elif callable(v) and hasattr(v, '__dict__'):
            v = v()
        else:
            if k == new_case:
                continue
            if new_case == 'lower':
                k = k.lower()
            elif new_case == 'upper':
                k = k.upper()
            elif new_case == 'title':
                k = k.title()

        result[k] = v
    return OrderedDict(result)

new_case = input("Enter the new key case (lower, upper, title): ")
result = replace_dict_key_case(params, new_case)
print(json.dumps(result, indent=4))
